for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];

    // Apply gravity force
    p.ay -= g;

    // Verlet integration for velocity
    p.vx += p.ax * deltaTime;
    p.vy += p.ay * deltaTime;
    p.vz += p.az * deltaTime;

    // Verlet integration for position
    p.x += p.vx * deltaTime;
    p.y += p.vy * deltaTime;
    p.z += p.vz * deltaTime;

    // Apply boundary conditions
    float boxLimit = boxWidth - h;
    float elasticity2 = elasticity * elasticity;

    // X boundaries
    if (p.x < -boxLimit) {
        p.x = -boxLimit;
        p.vx = -p.vx * elasticity;
    } else if (p.x > boxLimit) {
        p.x = boxLimit;
        p.vx = -p.vx * elasticity;
    }

    // Y boundaries
    if (p.y < -boxLimit) {
        p.y = -boxLimit;
        p.vy = -p.vy * elasticity;
    } else if (p.y > boxLimit) {
        p.y = boxLimit;
        p.vy = -p.vy * elasticity;
    }

    // Z boundaries
    if (p.z < -boxLimit) {
        p.z = -boxLimit;
        p.vz = -p.vz * elasticity;
    } else if (p.z > boxLimit) {
        p.z = boxLimit;
        p.vz = -p.vz * elasticity;
    }

    // Reset accelerations
    p.ax = 0.0f;
    p.ay = 0.0f;
    p.az = 0.0f;
}
